/* Dimension by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { align-items:center; padding:48px 24px; }
.ip-hero .ip-banner { opacity:.4; }
.ip-hero .ip-header { text-align:center; max-width:960px; padding:48px 24px; margin:auto; border-block:1px solid #ffffff99; align-self:center; }
.ip-title { text-transform:uppercase; letter-spacing:.16em; line-height:1.35; max-width:100%; font-size:clamp(var(--pager-title-min-size), calc(1rem + 3vw), var(--pager-title-size)); }
.ip-description { margin-inline:auto; }
.ip-hero .ip-navigation { justify-content:center; background:transparent; border:1px solid #ffffff99; border-radius:4px; color:#ffffff; padding:0 24px; margin:24px auto 0; }
.ip-block .block-heading { font-size:1.125rem; text-transform:uppercase; letter-spacing:.12em; }
@media(max-width:760px) { .ip-hero { padding:32px 20px; } .ip-hero .ip-header { padding:32px 0; } .ip-hero .ip-navigation { padding:8px 16px; gap:8px 20px; } }

.ip-hero:has(.ip-banner)::after { background:linear-gradient(#0009,#000b); }
.ip-hero:has(.ip-banner) .ip-description { color:#ffffff; opacity:1; }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
